layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); background-color: rgb(40, 40, 40); border-top: 1px solid rgb(74, 69, 64); border-right: 1px solid rgb(74, 69, 64); border-bottom: 1px solid rgb(74, 69, 64); border-left: 1px solid rgb(74, 69, 64); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 20px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); background-color: var(--ryt-header-bg); border-top: 1px solid rgb(46, 43, 40); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px solid var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: rgb(237, 230, 221); font-family: var(--ryt-font-heading); font-size: 40px; font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(237, 230, 221); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(237, 230, 221); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(237, 230, 221); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="header"] { border-bottom: 1px solid rgb(46, 43, 40); border-top: none }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 8px; font-family: var(--ryt-font-heading); font-size: 14.4px; font-weight: 600; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 8px; padding-bottom: 8px; padding-left: 8px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-top: 1px solid rgba(0, 0, 0, 0); border-right: 1px solid rgba(0, 0, 0, 0); border-bottom: 1px solid rgba(0, 0, 0, 0); border-left: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.2px; font-weight: 500; font-style: normal; line-height: 1.2; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: rgb(237, 230, 221) }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { border-top-color: rgb(74, 69, 64); border-right-color: rgb(74, 69, 64); border-bottom-color: rgb(74, 69, 64); border-left-color: rgb(74, 69, 64); background-image: initial; background-color: rgba(255, 255, 255, 0.05); color: rgb(237, 230, 221); color: rgb(200, 128, 74); border-bottom-color: rgb(200, 128, 74) }
[data-ryt="nav"] a:hover { color: rgb(237, 230, 221); background-image: initial; background-color: rgb(51, 46, 43) }
[data-ryt="brand"]:hover { color: rgb(237, 230, 221); background-image: initial; background-color: rgb(51, 46, 43) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(200, 128, 74); border-bottom-color: rgb(200, 128, 74) }
article[data-ryt="rec-card"]:hover { border-top-color: rgb(74, 69, 64); border-right-color: rgb(74, 69, 64); border-bottom-color: rgb(74, 69, 64); border-left-color: rgb(74, 69, 64); background-image: initial; background-color: rgba(255, 255, 255, 0.05); color: rgb(237, 230, 221); color: rgb(200, 128, 74); border-bottom-color: rgb(200, 128, 74) }
